INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Services > Services
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen Services in einem IT-System immer im Hintergrund laufen, um funktional zu sein?', 2, '[{"text": "Nein", "correct": true, "because": "Services können auch interaktiv oder zeitgesteuert sein"}, {"text": "Ja", "correct": false, "because": "Hintergrundbetrieb ist üblich, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Services ohne Abhängigkeiten zu anderen Systemkomponenten betrieben werden?', 2, '[{"text": "Ja", "correct": true, "because": "Eigenständige Services sind möglich"}, {"text": "Nein", "correct": false, "because": "Abhängigkeiten sind häufig, aber nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es möglich, einen Service zu starten, ohne dass die zugrunde liegende Hardware vollständig funktioniert?', 2, '[{"text": "Nein", "correct": true, "because": "Hardwarefehler verhindern oft die Ausführung"}, {"text": "Ja", "correct": false, "because": "Funktionierende Hardware ist meist Voraussetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Services in einem IT-System immer für den Endbenutzer sichtbar?', 2, '[{"text": "Nein", "correct": true, "because": "Viele Services laufen unsichtbar im Hintergrund"}, {"text": "Ja", "correct": false, "because": "Sichtbarkeit ist nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Services ohne regelmäßige Überwachung langfristig stabil bleiben?', 2, '[{"text": "Ja", "correct": true, "because": "Möglich, aber riskant ohne Monitoring"}, {"text": "Nein", "correct": false, "because": "Überwachung ist sinnvoll, aber nicht zwingend"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Begriff beschreibt einen Service, der kontinuierlich im Hintergrund läuft?', 3, '[{"text": "Daemon", "correct": true, "because": "Unix-Terminus für Hintergrundprozesse"}, {"text": "Thread", "correct": false, "because": "Teil eines Prozesses, kein eigenständiger Service"}, {"text": "Batch", "correct": false, "because": "Zeitgesteuerte Aufgabe, nicht kontinuierlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Betriebssystem verwaltet Services häufig über den "Task-Manager" oder "Dienste"?', 2, '[{"text": "Windows", "correct": true, "because": "Dienste sind zentral verwaltbar"}, {"text": "Linux", "correct": false, "because": "Nutzt eher systemd oder init"}, {"text": "macOS", "correct": false, "because": "Verwendet launchd"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel eines IT-Services?', 2, '[{"text": "Bereitstellung einer spezifischen Funktion", "correct": true, "because": "Services lösen konkrete Aufgaben"}, {"text": "Maximierung der Benutzerinteraktion", "correct": false, "because": "Nicht immer notwendig"}, {"text": "Reduktion der Hardwarekosten", "correct": false, "because": "Nebenaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann auftreten, wenn ein Service nicht korrekt konfiguriert ist?', 3, '[{"text": "Service startet nicht", "correct": true, "because": "Falsche Parameter verhindern Ausführung"}, {"text": "System wird schneller", "correct": false, "because": "Fehler verbessern nichts"}, {"text": "Automatische Neuinstallation", "correct": false, "because": "Nicht standardmäßig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wird unter Linux oft verwendet, um Services zu starten und zu stoppen?', 2, '[{"text": "systemctl", "correct": true, "because": "Teil von systemd"}, {"text": "taskmgr", "correct": false, "because": "Windows-spezifisch"}, {"text": "top", "correct": false, "because": "Nur zur Prozessüberwachung"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sollte ein gut implementierter IT-Service aufweisen?', 4, '[{"text": "Zuverlässigkeit", "correct": true, "because": "Minimiert Ausfälle"}, {"text": "Skalierbarkeit", "correct": true, "because": "Passt sich Last an"}, {"text": "Wartbarkeit", "correct": true, "because": "Ermöglicht Updates"}, {"text": "Hohe Farbqualität", "correct": false, "because": "Irrelevant für Services"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Services gibt es in einem IT-System?', 3, '[{"text": "Netzwerkdienste", "correct": true, "because": "z. B. DHCP oder DNS"}, {"text": "Hintergrunddienste", "correct": true, "because": "z. B. Logging"}, {"text": "Datenbankdienste", "correct": true, "because": "z. B. MySQL"}, {"text": "Grafikdesign-Services", "correct": false, "because": "Keine IT-Kategorie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei einem fehlerhaften Service auftreten?', 4, '[{"text": "Systeminstabilität", "correct": true, "because": "Abhängige Prozesse scheitern"}, {"text": "Datenverlust", "correct": true, "because": "Fehlerhafte Verarbeitung"}, {"text": "Sicherheitsrisiken", "correct": true, "because": "Schwachstellen entstehen"}, {"text": "Geringerer Stromverbrauch", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei der Implementierung eines neuen Services erforderlich?', 3, '[{"text": "Installation der Software", "correct": true, "because": "Grundlage des Services"}, {"text": "Konfiguration", "correct": true, "because": "Anpassung an Anforderungen"}, {"text": "Überwachung einrichten", "correct": true, "because": "Sichert Betrieb"}, {"text": "Farbauswahl der Benutzeroberfläche", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Abhängigkeiten können Services haben?', 3, '[{"text": "Andere Services", "correct": true, "because": "z. B. Datenbank für Webservice"}, {"text": "Hardware", "correct": true, "because": "z. B. Netzwerkkarte"}, {"text": "Betriebssystem", "correct": true, "because": "Plattformabhängigkeit"}, {"text": "Büroausstattung", "correct": false, "because": "Keine technische Abhängigkeit"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Service kann automatisch bei Systemstart aktiviert werden. b) Services sind immer netzwerkbasiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Autostart ja, Netzwerk nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Service kann mehrere Prozesse umfassen. b) Jeder Service benötigt eine grafische Benutzeroberfläche.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mehrere Prozesse ja, GUI nicht nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Services können durch Protokollierung überwacht werden. b) Ein Service ist unabhängig von der Systemkonfiguration.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Protokollierung ja, Konfiguration relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Service kann durch einen Neustart des Systems beeinflusst werden. b) Services sind immer eigenständige Programme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Neustart ja, Teil anderer Programme möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein fehlerhafter Service kann das gesamte System destabilisieren. b) Services müssen immer manuell gestartet werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Destabilisierung ja, Autostart möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

